      const buf2 = [];
      i++;
      while (i < lines.length && !/^\s*```/.test(lines[i])) buf2.push(lines[i++]);
      i++;
      const cls = fence.trim() ? ` class="language-${escapeHtml(fence.trim())}"` : "";
      out.push(`<pre><code${cls}>${escapeHtml(buf2.join("\n"))}</code></pre>`);
